public void execute(SessionData data,Element command){
  Element note=command.addElement("note");
  if (UserManager.getUserProvider().isReadOnly()) {
    note.addAttribute("type","error");
    note.setText("Users are read only. Changing password is not allowed.");
    return;
  }

  try {
    List<String> accountJids = data.getData().get("accountjid");
    List<String> passwords = data.getData().get("password");

    if (accountJids == null || accountJids.isEmpty() || passwords == null || passwords.isEmpty()) {
        note.addAttribute("type","error");
        note.setText("Invalid input data");
        return;
    }

    JID account=new JID(accountJids.get(0));
    String password=passwords.get(0);

    User user;
    try {
      user=UserManager.getInstance().getUser(account.getNode());
    }
    catch (  UserNotFoundException e) {
      note.addAttribute("type","error");
      note.setText("User does not exists.");
      return;
    }
    try {
      AuthFactory.getAuthProvider().authenticate(user.getUsername(),password);
    }
    catch (  UnauthorizedException e) {
      note.addAttribute("type","error");
      note.setText("Authentication failed.");
      return;
    }
    note.addAttribute("type","info");
    note.setText("Operation finished successfully.");
  }
  catch (Exception e) {
    note.addAttribute("type","error");
    note.setText("System error occurred: " + e.getMessage());
  }
}
